UPDATE oa_bank
SET deleted_flag = #{deletedFlag}
WHERE bank_id = #{bankId}

mapper.select:
SELECT *
FROM oa_bank
WHERE enterprise_id = #{enterpriseId}
AND account_number = #{accountNumber}
AND deleted_flag = #{deletedFlag}

    AND bank_id != #{excludeBankId}

SELECT oa_bank.*,
oa_enterprise.enterprise_name
FROM oa_bank
LEFT JOIN oa_enterprise ON oa_bank.enterprise_id = oa_enterprise.enterprise_id

    oa_bank.deleted_flag = #{queryForm.deletedFlag}

        AND (INSTR(oa_bank.bank_name,#{queryForm.keywords}) OR
        INSTR(oa_bank.account_name,#{queryForm.keywords}) OR
        INSTR(oa_bank.account_number,#{queryForm.keywords}) OR
        INSTR(oa_bank.create_user_name,#{queryForm.keywords}))


        AND DATE_FORMAT(oa_bank.create_time, '%Y-%m-%d') >= #{queryForm.startTime}


        AND DATE_FORMAT(oa_bank.create_time, '%Y-%m-%d') <= #{queryForm.endTime}


        AND oa_bank.disabled_flag = #{queryForm.disabledFlag}


        AND oa_bank.enterprise_id = #{queryForm.enterpriseId}



    ORDER BY oa_bank.create_time DESC

SELECT oa_bank.*,
       oa_enterprise.enterprise_name
FROM oa_bank
         LEFT JOIN oa_enterprise ON oa_bank.enterprise_id = oa_enterprise.enterprise_id
WHERE oa_bank.bank_id = #{bankId}
  AND oa_bank.deleted_flag = #{deletedFlag}
